{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is neutral or negative (≤ 0.00) to account for risk aversion or market cooling.",
    "Reduce forecast overshoots (especially after spikes) by 5–10% to prevent overreaction to short-term volatility.",
    "Apply mean reversion bias: if forecast deviates > ±10% from recent 7-day average, adjust toward it.",
    "For 30-day horizons, reduce forecast magnitude if sentiment shows early positive signals (e.g., +0.50) to avoid overconfidence.",
    "If true outcome consistently underperforms forecast (e.g., 3–5% below), apply a 3–5% downward bias for next period.",
    "Lag correction: if forecast is significantly ahead of recent history (e.g., > 15% above 14-day moving average), reduce by 10–15% to account for delayed market response."
  ]
}
